\"\"\"標準ライブラリだけで XLSX の保存値を読み、照合表と注記を出力する。\"\"\"
import json, re, zipfile, xml.etree.ElementTree as ET
from pathlib import Path
N={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
def book(path):
    with zipfile.ZipFile(path) as z:
        ss=[''.join(t.text or '' for t in si.iter('{'+N['m']+'}t')) for si in ET.fromstring(z.read('xl/sharedStrings.xml')).findall('m:si',N)] if 'xl/sharedStrings.xml' in z.namelist() else []
        rel={x.attrib['Id']:x.attrib['Target'] for x in ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))}
        out={}
        for s in ET.fromstring(z.read('xl/workbook.xml')).find('m:sheets',N):
            p=rel[s.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']]
            p=p.lstrip('/') if p.startswith('/') else 'xl/'+p
            cells={}
            for c in ET.fromstring(z.read(p)).findall('.//m:sheetData/m:row/m:c',N):
                v=c.find('m:v',N); typ=c.attrib.get('t')
                if typ=='inlineStr': value=''.join(t.text or '' for t in c.findall('.//m:t',N))
                elif v is None: continue
                elif typ=='s':value=ss[int(v.text)]
                elif typ in ('str','e'):value=v.text
                else:
                    value=float(v.text);value=int(value) if value.is_integer() else value
                cells[c.attrib['r']]=value
            out[s.attrib['name']]=cells
        return out
L=book('longterm_1998_2025.xlsx')
A={y:book(next(Path('annual').glob(f'r{y-2018}_*'))) for y in range(2019,2023)}
if __name__=='__main__':
    for name in ['F7','F8','在院患者数','その他の疾患分類','目次']:
        print('\\nLONG',name)
        for c,v in L[name].items():
            if isinstance(v,str) and (not c.startswith('A') or int(re.sub(r'\\D','',c))>50):print(c,repr(v))
    for y,b in A.items():
        print('\\nANNUAL',y)
        for c,v in b['Ⅲ.2.(5)'].items():
            r=int(re.sub(r'\\D','',c))
            if r>50:print(c,repr(v))
        for s in b:
            if s.strip()=='はじめに':
                print(s,b[s])
PY
